/*selectRefHdInfoList*/
SELECT (SELECT CASE WHEN #{st_item_no} BETWEEN '11250000' AND '11299999' THEN 'KR03' ELSE CASE WHEN #{st_item_no} BETWEEN '11300000' AND '11499999' THEN 'KR04' ELSE CASE WHEN #{st_item_no} BETWEEN '11500000' AND '11599999' THEN 'KR07' END END END FROM DUAL) AS REF_PR_FLAG , (SELECT CASE WHEN #{st_item_no} BETWEEN '11250000' AND '11299999' THEN 'Operating supplies' ELSE CASE WHEN #{st_item_no} BETWEEN '11300000' AND '11499999' THEN 'Spare parts' ELSE CASE WHEN #{st_item_no} BETWEEN '11500000' AND '11599999' THEN 'Non Stock' END END END FROM DUAL) AS REF_PR_TEXT
, A.BUYER_ITEM_NO , A.DESCRIPTION , A.SPECIFICATION , A.UNIT_PRICE
, to_char(sysdate,'YYYYMMDD') CURDATE , to_char(sysdate+7,'YYYYMMDD') CURDATEPLUS7 ,(SELECT KEY_10 AS MG_NOTE FROM ICOMTRXL WHERE DOC_NAME = 'KIM_PR' AND (TARGET,KEY_1,KEY_7,KEY_8) IN ( SELECT MAX(TARGET),MAX(KEY_1),MAX(KEY_7),MAX(KEY_8) FROM ICOMTRXL WHERE DOC_NAME = 'KIM_PR' AND TARGET = #{st_buyer} AND KEY_1 = #{st_yuhan_saperp_flag} -- AND KEY_7 = 'KT3' ) AND ROWNUM = 1 ) MG_NOTE_TEXT
FROM ICOMCQDT A, ICOMCMPY B WHERE 1=1 AND A.BUYER = B.BYCA_COMORG_CODE AND B.COM_CODE = #{st_buyer} AND A.BUYER_ITEM_NO = #{st_item_no} AND A.CONTRACT_NO = #{st_contract_no} AND A.CONTRACT_SEQ = #{st_contract_seq}


/*selectLegacyUserIdList*/

	SELECT	
		A.LEGACY_USER_ID	
	FROM ICOMLUSR A	
	WHERE 1=1	
		AND A.USER_ID = #{userid}


/*selectUserNameLoc*/

		SELECT	
			USER_NAME_LOC	
		FROM ICOMLUSR	
		WHERE 1=1	
			AND COM_CODE  = #{value1} 
			AND LEGACY_USER_ID = #{value2}


/*selectUserAddressLoc*/

		SELECT	
			ZIP_CODE || ' ' || ADDRESS_LOC AS USER_ADDRESS
		FROM ICOMLUSR	
		WHERE 1=1	
			AND COM_CODE  = #{value1} 
			AND LEGACY_USER_ID = #{value2}


		/*selectCenterCode*/

				SELECT	
					TEXT1	
				FROM ICOMCOD2	
				WHERE COMPANY_CODE =#{value1} 
					AND CODE = #{value2} 





            AND TEXT4 = 'PROFIT'	




          AND TEXT4 = 'COST'	





		AND TYPE = 'C001'


/*selectprofitSegmentCode*/

		SELECT										         
			TEXT1								 
		FROM ICOMCOD2 							  
		WHERE COMPANY_CODE = #{value1} 	 
			AND CODE = #{value2} 			  
			AND TYPE = 'M014'

