/*saveBuyerYuhanRetUpdate*/


		UPDATE ICOMCART	
		SET REF_PR_NO = #{st_ref_no} 		
			, MG_NOTE = #{st_mg_note} 		
		WHERE 1=1	
			AND BUYER = #{buyer} 		
			AND USER_ID = #{userid} 		
			AND BUYER_ITEM_NO = #{st_item_no}


/*saveUserAddressUpdate*/

		UPDATE ICOMLUSR
		SET ZIP_CODE = SUBSTR(#{st_location_name},1,7)
			, ADDRESS_LOC = SUBSTR(#{st_location_name},9)
			, ADDRESS_LOC1 = ''
			, ADDRESS_LOC2 = ''
			, ZIP_KEY = ''
		WHERE 1=1
			AND COM_CODE = #{buyer}
			AND LEGACY_USER_ID = #{st_req_user_id}
